P4C4 = LIEN + 'le-gout-du-futur-aux-nouvelles-frontieres-de-l-humanite/chapitre4'
DOC = 'Document budgétaire de LFI du 14/10/2026 (cote D : document partisan, qui dit lui-même ne pas constituer un chiffrage complet)'

PROGRAMME = {
    'nom': 'La France insoumise (2027)', 'cle': 'lfi', 'debut': 2028, 'regime': 2032,
    'calendrier': "Premier exercice après l'élection de 2027 = 2028 (le budget 2027 est voté avant l'élection) ; régime des mesures en 2032, fin de mandat. Les montants « année 1 » du document de LFI sont lus comme ceux de 2028.",
    'sources_chiffrage': DOC, 'macro': 'reference',
}


def tri(b, c, h, **kw):
    d = {'forme': 'tri', 'bas': b, 'central': c, 'haut': h}
    d.update(kw)
    return d


DERIVE = lambda lam=0.6: tri(0.9, 1.0, 1.3)   # dérive de coût d'une mesure chiffrée par son auteur seul (H-DERIVE)


def cout_lfi(id_, chap, lib, cit, lien, montant, an1=None, interp='', src=DOC, cote='D', facteur='cout', lam=0.6):
    """Mesure chiffrée par LFI seul : le montant du document est le central ; borne basse 0,9x, borne haute 1,3x (H-DERIVE)."""
    return dict(id=id_, chapitre=chap, libelle=lib, citation=cit, lien=lien, sens='depense', levier='cout_unitaire',
                valeur=tri(0.9 * montant, montant, 1.3 * montant), an1=an1 if an1 is not None else montant, interpretation=interp, facteur=facteur, **{'lambda': lam},
                hypotheses=[('H-DERIVE', "Aucune contre-estimation lue : montant de LFI = valeur centrale ; support 0,9 à 1,3 fois (asymétrique : les coûts publics dérivent plus souvent à la hausse). Convention, sans source.", src, cote, 'auteur = le programme chiffré')])


